-- Usage (after applying goose migrations):
-- psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -v code=Ab12Cde \
--   -v legacy_tenant=a-b-com -v new_tenant=domain:a.b.com \
--   -f scripts/rekey-link.sql
--
-- Review the link's original owner BEFORE running this! Legacy tenant slugs
-- can represent more than one email domain, so do not rekey whole tenants.
-- A single transaction updates BOTH the link and its click records, preserving
-- the composite foreign key. New tenant must be exactly the canonical key
-- generated by tenantFromSubject ("domain:<domain>" / "subject:<base64url>").
BEGIN;
SET CONSTRAINTS clicks_tenant_code_fk DEFERRED;

UPDATE links
SET tenant_id = :'new_tenant'
WHERE code = :'code' AND tenant_id = :'legacy_tenant'
RETURNING code, tenant_id;

UPDATE clicks
SET tenant_id = :'new_tenant'
WHERE code = :'code' AND tenant_id = :'legacy_tenant';

COMMIT;
